// REG guard for the gh-1000 rework CI breakage family: a merge of main
// into the feature branch resolved `bin/fah.dart` and
// `lib/src/cli/session_commands.dart` as TAKE-OURS, silently deleting
// main's boot wiring (wire-serve interception #1103, the jsr pass-through
// gh-1033, session rotation warnings gh-1077, the provider-timeout env
// override #1036, gh-1059 boot diagnostics, the fresh-install wizard #969,
// the quota feed #823, skill toggles #1151, the gh-968 resume parity
// budget + mailbox-prefix projection, and the #964 authHeader restore).
// Nothing failed to COMPILE — the dropped call sites went away together
// with their imports — so `dart analyze` stayed green and the break only
// surfaced as red CI legs (and a `fa wire-serve --stdio` that answered
// "unknown argument: --stdio").
//
// Hermetic source grep (no PTY, no network), runs in the DEFAULT suite so
// the pre-commit fast gate enforces it: every boot-wiring symbol that the
// lib/bin layers provide for the executable MUST be referenced from the
// executable's main. A future rename updates the guard in the same commit
// — a drop is never silent again.
import 'dart:io';

import 'package:test/test.dart';

/// Each entry: file → symbols whose ONLY reason to exist is the bin main
/// wiring (or, for the `part of agent_cli.dart` session extension, the
/// resume glue main-side boot mirrors). The comment names the feature so
/// an intentional removal updates this list knowingly.
const _requiredReferences = <String, List<String>>{
  'bin/fah.dart': [
    // `fa wire-serve` interception (issue #1103).
    'splitWireServeArgs',
    // `fa jsr …` pass-through (gh-1033).
    'runJsrCliCommand',
    // Session segment rotation warnings on stderr (gh-1077).
    'onRotationWarning',
    // FA_PROVIDER_TIMEOUT_SECONDS env override fold-in (issue #1036).
    'applyProviderTimeoutEnvOverride',
    // Boot key diagnostics — every read logged / nothing-resolved warning
    // (gh-1059).
    'secureKeyBootDiagnostics',
    // Fresh-install guided add-provider wizard (issue #969).
    'freshInstallProviderState',
    // Provider quota badge + queue quota feed rebind (issue #823).
    'attachProviderQueueQuotaFeed',
    // Global per-skill toggles (`skills:` section, issue #1151).
    'skillToggles',
    // gh-1198: the --stream-thinking flag > output.streamThinking config
    // resolution wired into the run config.
    'resolveStreamThinking',
  ],
  'lib/src/cli/session_commands.dart': [
    // gh-968 (AC-R3): resume prices the FIRST request (parity budget).
    'resumeParityBudget',
    // gh-968: the messaging section's mailbox prefix is projected at
    // resume, before mailbox-prefix sync runs in boot order.
    '_assignMailboxPrefix',
    // Issue #964: a restored endpoint's saved authHeader survives.
    'authHeaderForBaseUrl',
  ],
};

void main() {
  test('bin main keeps every boot-wiring symbol (gh-1000 rework reg)', () {
    final violations = <String>[];
    _requiredReferences.forEach((path, symbols) {
      final file = File(path);
      if (!file.existsSync()) {
        violations.add('$path: FILE MISSING');
        return;
      }
      final source = file.readAsStringSync();
      for (final symbol in symbols) {
        if (!source.contains(symbol)) {
          violations.add('$path: no reference to `$symbol`');
        }
      }
    });
    expect(
      violations,
      isEmpty,
      reason: '''
A boot-wiring symbol disappeared from the executable's main. This is the
gh-1000-rework failure shape: a take-ours merge resolution deletes main's
call sites together with their imports, analyze stays green, and the
feature dies silently (wire-serve, jsr, rotation warnings, timeout env
override, boot diagnostics, fresh-install wizard, quota feed, skill
toggles, resume parity). If the symbol moved INTENTIONALLY, update
_requiredReferences in the same commit — never delete the reference
without a replacement wiring.
''',
    );
  });
}

// gh-1000 round-3 review (T6/T4): the BOOT-side pin resolution lives in
// bin/fah_boot_restore.dart — its E1 degradation (a state naming an entry
// that no longer exists) is pinned here, mirroring the session-restore
// tests in test/cli/agent_cli_folder_model_restore_test.dart.
import 'dart:io';

import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:test/test.dart';

import '../bin/fah_boot_restore.dart';

void main() {
  const kimiUrl = 'https://api.kimi.com/coding/v1';
  final registry = [
    CustomProviderEntry(
      name: 'ira-1',
      apiType: 'kimi',
      baseUrl: kimiUrl,
      modelId: 'k3-256k',
      keyName: 'FA_KEY_API_KIMI_COM_IRA_1',
    ),
    CustomProviderEntry(
      name: 'kimi_me',
      apiType: 'openai',
      baseUrl: kimiUrl,
      modelId: 'k3-256k',
      keyName: 'FA_KEY_API_KIMI_COM_KIMI_ME',
    ),
  ];

  test('a state naming a live entry resolves THAT entry', () {
    final pin = resolveBootFolderPin(
      state: FolderModelState(
        providerKind: 'openai-completions',
        modelId: 'k3-256k',
        baseUrl: kimiUrl,
        customProvider: 'kimi_me',
      ),
      entries: registry,
    );
    expect(pin.entry?.name, 'kimi_me');
    expect(pin.note, isNull);
  });

  test('a state naming a deleted entry degrades with the E1 note', () {
    final pin = resolveBootFolderPin(
      state: FolderModelState(
        providerKind: 'openai-completions',
        modelId: 'k3-256k',
        baseUrl: kimiUrl,
        customProvider: 'gone-provider',
      ),
      entries: registry,
    );
    expect(pin.entry, isNull);
    expect(pin.note, allOf(contains('gone-provider'), contains('no longer')));
  });

  test('a pre-pin state (no provider name) resolves nothing, no note', () {
    final pin = resolveBootFolderPin(
      state: const FolderModelState(
        providerKind: 'openai-completions',
        modelId: 'k3-256k',
        baseUrl: kimiUrl,
      ),
      entries: registry,
    );
    expect(pin.entry, isNull);
    expect(pin.note, isNull);
  });
  test('a null state (nothing saved) resolves nothing, no note', () {
    final pin = resolveBootFolderPin(state: null, entries: registry);
    expect(pin.entry, isNull);
    expect(pin.note, isNull);
  });

  // Sanity: the helper's home compiles against the executable's own
  // imports (bin/fah.dart imports it).
  test('fah.dart still imports the helper (wiring guard companion)', () {
    final fah = File('bin/fah.dart').readAsStringSync();
    expect(fah, contains("import 'fah_boot_restore.dart';"));
    expect(fah, contains('resolveBootFolderPin('));
  });
}

/// One HEP JSONL line to stdout, flushed immediately (issue #155): a
/// supervisor tailing the pipe must never wait on a buffer.
void _writeHepLine(String line) {
  stdout.writeln(line);
  stdout.flush();
}

/// One stream-json NDJSON line to stdout, flushed immediately (issue
/// #695): same live-pipe contract as HEP — `| jq` consumers tail the
/// stream line by line, and jsonEncode output is always single-line.
void _writeStreamJsonLine(String line) {
  stdout.writeln(line);
  stdout.flush();
}

/// The mime reported when the magic-byte sniff misses — callers treat it
/// as "not an image" (issue #196 `--attach` passthrough).
const _unknownAttachMime = 'application/octet-stream';

/// Image type by magic bytes (issue #155 `--attach`): the file extension
/// is untrusted; the first bytes are. png/jpeg/gif/webp covered, else
/// [_unknownAttachMime].
String _sniffMime(Uint8List bytes) {
  bool startsWith(List<int> magic) {
    if (bytes.length < magic.length) return false;
    for (var i = 0; i < magic.length; i++) {
      if (bytes[i] != magic[i]) return false;
    }
    return true;
  }

  const png = [137, 80, 78, 71, 13, 10, 26, 10];
  if (startsWith(png)) return 'image/png';
  if (startsWith([0xFF, 0xD8, 0xFF])) return 'image/jpeg';
  if (startsWith([0x47, 0x49, 0x46, 0x38])) return 'image/gif';
  if (startsWith([0x52, 0x49, 0x46, 0x46]) &&
      bytes.length > 12 &&
      bytes[8] == 0x57 &&
      bytes[9] == 0x45 &&
      bytes[10] == 0x42 &&
      bytes[11] == 0x50) {
    return 'image/webp';
  }
  return _unknownAttachMime;
}

Never _exitWithVersion(String version, {String? output}) {
  if (output == 'json') {
    // Machine-readable for supervisors (issue #155): version + HEP
    // protocol version, one JSON object.
    stdout.writeln(jsonEncode({'version': version, 'hep': hepVersion}));
    exit(0);
  }
  stdout.writeln('fa $version');
  exit(0);
}

/// Writes an uncaught error to `~/.fah/crash.log` and stderr, then exits
/// non-zero. This is the last-resort handler so users can report what
/// happened instead of the CLI silently disappearing.
void _handleUncaughtError(Object error, StackTrace stackTrace) {
  final message = 'fa crashed: $error';
  stderr.writeln(message);
  if (error is SessionException ||
      message.contains('Failed to create session directory')) {
    stderr.writeln(
      '\nTip: If this is a permission issue with session storage, you can fix it by running:\n'
      '  sudo chown -R \$(whoami) ~/Library/"Group Containers"/group.dev.fa1.shared\n'
      '  chmod -R u+rwx ~/Library/"Group Containers"/group.dev.fa1.shared\n'
      'Or start fa with a custom session storage path:\n'
      '  fa --session-root ~/.fah/sessions\n',
    );
  }
  try {
    final home =
        Platform.environment['HOME'] ?? Platform.environment['USERPROFILE'];
    if (home != null && home.isNotEmpty) {
      final dir = Directory('$home/.fah');
      dir.createSync(recursive: true);
      final log = File('${dir.path}/crash.log');
      final timestamp = DateTime.now().toUtc().toIso8601String();
      final version = _packageVersion();
      final buffer = StringBuffer()
        ..writeln('timestamp: $timestamp')
        ..writeln('version: $version')
        ..writeln('type: ${error.runtimeType}')
        ..writeln('error: $error')
        ..writeln('stack:')
        ..writeln(stackTrace);
      log.writeAsStringSync('$buffer\n', mode: FileMode.append);
      stderr.writeln('details appended to ${log.path}');
    }
  } on Object catch (e) {
    stderr.writeln('could not write crash log: $e');
  }
  stderr.writeln('Run with --help for usage.');
  exit(1);
}

Future<void> main(List<String> args) async {
  // Session segment rotation warnings (fa gh-1077): the session layer has
  // no console dependency — the CLI surfaces hard-cap truncations and
  // rotation fallbacks on stderr.
  JsonlSessionStorage.onRotationWarning = stderr.writeln;
  await runZoned(
    () => _runApp(args),
    zoneSpecification: ZoneSpecification(
      handleUncaughtError: (self, parent, zone, error, stackTrace) {
        // fa_hub_client can fail a LEAKED waiter (no listener left) with
        // StateError('connection closed') when the socket drops — e.g. a
        // flush() waiter abandoned after _send threw on a dead socket.
        // The error lands here as an unhandled async error no call-site
        // try/catch can reach; the fabric already fell back to files, so
        // log it and keep running instead of crashing the CLI.
        if (isHubConnectionTeardown(error)) {
          stderr.writeln(
            'fa: hub connection closed mid-operation — '
            'continuing on the file fabric',
          );
          return;
        }
        _handleUncaughtError(error, stackTrace);
      },
    ),
  );
}

Model _buildModel(CliArgs args, {List<String>? input, String? thinkingLevel}) {
  return buildCliDefaultModel(
    args.provider,
    modelId: args.model,
    baseUrl: args.baseUrl,
    input: input,
    thinkingLevel: thinkingLevel,
  );
}

String _resolveApiKey(
  String provider,
  SecureKeyCache keys, {
  String? fallback,
  String? baseUrl,
  Iterable<String>? scopedKeyNames,
}) {
  final key =
      optionalProviderApiKey(
        provider,
        keys,
        baseUrl: baseUrl,
        scopedKeyNames: scopedKeyNames,
      ) ??
      fallback;
  if (key == null || key.isEmpty) {
    _fail(
      'missing API key: set ${apiKeyEnvNames(provider).first} in the '
      'environment',
    );
  }
  return key;
}

/// Built-in plugins available via `--plugin <name>` or `.fah/packages.yaml`.
/// [hubPlugin] is the process's single hub client instance — the same one
/// the settings-hub DAP / Hub flow reads its snapshot through. When
/// [fabricDeliversMail] is set the hub-backed messaging repository owns
/// hub mail delivery and the plugin host registers no separate inbox.
FahPlugin? _builtInPlugin(
  String name,
  HubPlugin hubPlugin, {
  required bool fabricDeliversMail,
  Map<String, String>? dapEnvironment,
}) {
  return switch (name) {
    'hub' => HubPluginHost(
      hubPlugin,
      environment: dapEnvironment,
      fabricDeliversMail: fabricDeliversMail,
    ),
    'inspect_image' => const InspectImagePlugin(),
